INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64628548', 64628548, 'analyze_legacy', 'Kementerian Hukum', 'central', '03 BALAI HARTA PENINGGALAN SEMARANG', 'Pengadaan Peralatan Fasilitas Perkantoran Belanja Modal Peralatan dan Mesin berupa AC Split Balai Harta Peninggalan Semarang Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 60000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '5 unit', 'Pengadaan AC Split Beserta Pemasangan Paket pekerjaan ini adalah pengadaan Air Conditioner (AC) split beserta pemasangan untuk mendukung kenyamanan dan kelancaran kegiatan perkantoran pada satuan kerja. Pekerjaan meliputi penyediaan unit AC baru sesuai spesifikasi teknis yang dipersyaratkan serta pelaksanaan pemasangan hingga unit siap digunakan dengan baik dan aman. Ruang lingkup pekerjaan mencakup: 1. Pengadaan AC split kapasitas 2 PK sebanyak 7 (tujuh) unit sesuai spesifikasi teknis yang ditetapkan, termasuk unit indoor dan outdoor. 2. Pelaksanaan pemasangan AC yang meliputi: o Penempatan unit indoor dan outdoor pada lokasi yang telah ditentukan. o Pemasangan bracket indoor dan outdoor. o Instalasi pipa refrigerant, kabel listrik, dan pipa pembuangan air (drain). o Pengisian dan pengecekan refrigerant (Freon R-32) apabila diperlukan. 3. Pengujian fungsi AC setelah pemasangan untuk memastikan unit beroperasi dengan normal, optimal, dan aman. 4. Pembersihan area kerja setelah pekerjaan pemasangan selesai. 5. Penyerahan hasil pekerjaan yang dibuktikan dengan Berita Acara Serah Terima (BAST). Seluruh pekerjaan harus dilaksanakan sesuai dengan standar teknis, ketentuan keselamatan kerja, serta spesifikasi yang telah ditentukan, dengan jangka waktu pelaksanaan sesuai yang ditetapkan dalam dokumen pengadaan.', 'Pengadaan AC Split Beserta Pemasangan 1. Jenis Pekerjaan - Pengadaan Air Conditioner (AC) split beserta pemasangan. 2. Jumlah dan Kapasitas - AC split kapasitas 2 PK - Jumlah: 7 (tujuh) unit 3. Ruang Lingkup Pemasangan - Pemasangan unit indoor dan outdoor sesuai lokasi yang ditentukan. - Pemasangan bracket indoor dan outdoor. - Instalasi pipa refrigerant, kabel listrik, dan pipa pembuangan (drain). - Pengisian dan pengecekan refrigerant apabila diperlukan. - Pengujian fungsi dan kinerja AC hingga beroperasi normal. 4. Standar Pekerjaan - Pemasangan dilakukan oleh teknisi yang berpengalaman dan kompeten. - Pelaksanaan pekerjaan sesuai standar keselamatan dan ketentuan teknis yang berlaku. - Hasil pemasangan rapi, aman, dan tidak mengganggu lingkungan sekitar. 5. Standar Pekerjaan - Pemasangan dilakukan oleh teknisi yang berpengalaman dan kompeten. - Pelaksanaan pekerjaan sesuai standar keselamatan dan ketentuan teknis yang berlaku. - Hasil pemasangan rapi, aman, dan tidak mengganggu lingkungan sekitar. 6. Standar Pekerjaan - Pemasangan dilakukan oleh teknisi yang berpengalaman dan kompeten. - Pelaksanaan pekerjaan sesuai standar keselamatan dan ketentuan teknis yang berlaku. Hasil pemasangan rapi, aman, dan tidak mengganggu lingkungan sekitar. 7. Standar Pekerjaan - Pemasangan dilakukan oleh teknisi yang berpengalaman dan kompeten. - Pelaksanaan pekerjaan sesuai standar keselamatan dan ketentuan teknis yang berlaku. - Hasil pemasangan rapi, aman, dan tidak mengganggu lingkungan sekitar. 8. Serah Terima Pekerjaan Pekerjaan dinyatakan selesai setelah dilakukan pemeriksaan dan ditandai dengan Berita Acara Serah Terima (BAST).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1631365);
