INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64590057', 64590057, 'analyze_legacy', 'Kab. Pesisir Selatan', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'Perencanaan Pembangunan Saluran Drainase Kantor Camat Basa Ampek Balai Tapan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Sumatera Barat, Pesisir Selatan (Kab.)', 9020000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Ruang Lingkup Pekerjaan Perencanaan 1. Pengumpulan Data; 2. Survei dan Investigasi; 3. Penyusunan Konsep Perencanaan; 4. Perencanaan Teknis (Detail Engineering Design / DED); 5. Penyusunan Dokumen Biaya dan Waktu; 6. Koordinasi dan Konsultasi; 7. Finalisasi Dokumen Perencanaan.', 'Spesifikasi Pekerjaan Perencanaan 1. Umum Pekerjaan perencanaan merupakan kegiatan penyusunan dokumen teknis sebagai dasar pelaksanaan pembangunan, yang meliputi perencanaan teknis, perhitungan, gambar kerja, serta dokumen pendukung lainnya sesuai ketentuan dan standar yang berlaku. 2. Maksud dan Tujuan • Menghasilkan dokumen perencanaan yang tepat guna, aman, ekonomis, dan berkelanjutan • Menjadi acuan dalam pelaksanaan konstruksi • Menjamin kesesuaian desain dengan kebutuhan dan kondisi lapangan 3. Ruang Lingkup Pekerjaan • Pengumpulan data dan survei lapangan • Analisis teknis dan non-teknis • Penyusunan konsep desain dan alternatif perencanaan • Penyusunan Detail Engineering Design (DED) • Penyusunan gambar kerja dan spesifikasi teknis • Penyusunan Rencana Anggaran Biaya (RAB) dan jadwal pelaksanaan • Konsultasi dan koordinasi dengan pemberi tugas • Finalisasi dan penyerahan dokumen perencanaan 4. Standar dan Acuan Teknis • Standar Nasional Indonesia (SNI) yang berlaku • Peraturan perundang-undangan terkait konstruksi • Pedoman teknis instansi terkait • Ketentuan keselamatan dan lingkungan 5. Metodologi Perencanaan • Survei dan pengumpulan data lapangan • Analisis kebutuhan dan kondisi eksisting • Perhitungan teknis sesuai disiplin ilmu • Penyusunan dan evaluasi desain • Revisi dan penyempurnaan desain 6. Persyaratan Tenaga Ahli • Tenaga ahli bersertifikat dan berpengalaman sesuai bidangnya • Pendidikan minimal S1 Teknik yang relevan • Pengalaman kerja sesuai kompleksitas pekerjaan 7. Produk yang Dihasilkan • Laporan pendahuluan • Laporan antara • Laporan akhir perencanaan • Gambar rencana dan gambar detail • Spesifikasi teknis • RAB dan dokumen pendukung lainnya', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1635027);
