INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64573738', 64573738, 'analyze_legacy', 'Kab. Pesisir Selatan', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'Pengawasan Pembangunan Saluran Drainase Lingkungan Paket II', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Sumatera Barat, Pesisir Selatan (Kab.)', 30290000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Ruang Lingkup Pekerjaan : 1. Mengawasi pelaksanaan pekerjaan agar sesuai gambar rencana, spesifikasi teknis, dan kontrak; 2. Memastikan pekerjaan berjalan sesuai jadwal (time schedule); 3. Mengawasi penggunaan material, tenaga kerja, dan peralatan; 4. Mengendalikan mutu, biaya, dan waktu pekerjaan.', '1. Ruang Lingkup Pekerjaan • Mengawasi pelaksanaan pekerjaan agar sesuai gambar rencana, spesifikasi teknis, dan kontrak • Memastikan pekerjaan berjalan sesuai jadwal (time schedule) • Mengawasi penggunaan material, tenaga kerja, dan peralatan • Mengendalikan mutu, biaya, dan waktu pekerjaan 2. Tugas dan Tanggung Jawab • Melakukan pengawasan harian di lapangan • Memeriksa kualitas pekerjaan dan material yang digunakan • Mengidentifikasi dan melaporkan penyimpangan pekerjaan • Memberikan arahan teknis kepada pelaksana di lapangan • Membuat laporan harian, mingguan, dan bulanan • Menghadiri rapat koordinasi proyek • Memastikan penerapan K3 (Keselamatan dan Kesehatan Kerja) • Melakukan pengecekan hasil pekerjaan sebelum diserahterimakan 3. Persyaratan Teknis • Pendidikan minimal: D3/S1 Teknik (Sipil/Mesin/Elektro, sesuai proyek) • Pengalaman kerja pengawasan minimal X tahun • Memahami gambar kerja, RAB, dan spesifikasi teknis • Mampu menggunakan alat ukur dan software pendukung (mis. AutoCAD, Excel) 4. Wewenang • Menegur pelaksana jika pekerjaan tidak sesuai spesifikasi • Menolak pekerjaan atau material yang tidak memenuhi standar • Memberikan rekomendasi perbaikan pekerjaan 5. Output Pekerjaan • Laporan pengawasan berkala • Dokumentasi pekerjaan (foto, catatan lapangan) • Berita acara pemeriksaan dan serah terima pekerjaan 6. Standar & Acuan • Spesifikasi teknis proyek • Standar nasional (SNI) / standar internasional terkait • Peraturan keselamatan dan ketenagakerjaan yang berlaku', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1638467);
